import os
import re
import gzip
import base64
import random
import secrets
import logging
from datetime import datetime, timedelta, timezone
from functools import wraps

import psycopg2
import psycopg2.extras
from flask import Flask, request, session, jsonify, g, Response
from werkzeug.exceptions import HTTPException
from werkzeug.security import generate_password_hash, check_password_hash

SHARD_CAP = 50
ONLINE_WINDOW = timedelta(seconds=30)
START_MONEY = 5000
GANG_COST = 300000
LOCKPICK_PRICE = 700000
CAR_PRICE = 150000
SHOP = {"lockpick": {"name": "ابزار قفل‌شکن", "price": LOCKPICK_PRICE}}
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

DATABASE_URL = os.environ.get("DATABASE_URL", "")

app = Flask(__name__)
app.secret_key = os.environ.get("SECRET_KEY") or secrets.token_hex(32)
app.config.update(
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=bool(os.environ.get("RENDER")),
    PERMANENT_SESSION_LIFETIME=timedelta(days=30),
)

SCHEMA = """
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    name TEXT NOT NULL,
    money BIGINT NOT NULL DEFAULT 5000,
    rp INT NOT NULL DEFAULT 0,
    gang_id INT,
    created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS gangs (
    id SERIAL PRIMARY KEY,
    name TEXT UNIQUE NOT NULL,
    owner_id INT,
    bank BIGINT NOT NULL DEFAULT 0,
    rp INT NOT NULL DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS shards (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS presence (
    user_id INT PRIMARY KEY,
    shard_id INT NOT NULL,
    last_seen TIMESTAMPTZ NOT NULL
);
CREATE TABLE IF NOT EXISTS messages (
    id BIGSERIAL PRIMARY KEY,
    shard_id INT NOT NULL,
    from_id INT NOT NULL,
    to_id INT,
    text TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS signals (
    id BIGSERIAL PRIMARY KEY,
    to_id INT NOT NULL,
    from_id INT NOT NULL,
    kind TEXT NOT NULL,
    payload TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now()
);
CREATE TABLE IF NOT EXISTS items (
    user_id INT NOT NULL,
    item TEXT NOT NULL,
    qty INT NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, item)
);
CREATE TABLE IF NOT EXISTS vehicles (
    id SERIAL PRIMARY KEY,
    owner_id INT NOT NULL,
    name TEXT NOT NULL,
    locked BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT now()
);
"""


def init_db():
    with psycopg2.connect(DATABASE_URL) as conn:
        with conn.cursor() as cur:
            cur.execute(SCHEMA)


if DATABASE_URL:
    try:
        init_db()
    except Exception as exc:  # another worker may be creating tables at the same time
        logging.warning("init_db: %s", exc)


def db():
    if "db" not in g:
        g.db = psycopg2.connect(DATABASE_URL, cursor_factory=psycopg2.extras.RealDictCursor)
    return g.db


@app.teardown_appcontext
def close_db(_exc=None):
    conn = g.pop("db", None)
    if conn is not None:
        conn.close()


def q(sql, params=(), one=False, write=False):
    cur = db().cursor()
    cur.execute(sql, params)
    res = None
    if cur.description is not None:
        res = cur.fetchone() if one else cur.fetchall()
    if write:
        db().commit()
    return res


def utcnow():
    return datetime.now(timezone.utc)


def body():
    return request.get_json(silent=True) or {}


def fail(msg, code=400):
    return jsonify(ok=False, error=msg), code


def login_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        uid = session.get("uid")
        if not uid:
            return jsonify(ok=False, error="login"), 401
        g.uid = uid
        return f(*args, **kwargs)
    return wrapper


def login_session(uid):
    session.permanent = True
    session["uid"] = uid


def user_row(uid):
    return q(
        """SELECT u.id, u.name, u.email, u.money, u.rp, u.gang_id, gg.name AS gang_name
           FROM users u LEFT JOIN gangs gg ON gg.id = u.gang_id WHERE u.id = %s""",
        (uid,), one=True)


def assign_shard(uid):
    now = utcnow()
    row = q("SELECT shard_id FROM presence WHERE user_id = %s", (uid,), one=True)
    if row:
        q("UPDATE presence SET last_seen = %s WHERE user_id = %s", (now, uid), write=True)
        return row["shard_id"]
    shards = q(
        """SELECT s.id, (SELECT COUNT(*) FROM presence p
                         WHERE p.shard_id = s.id AND p.last_seen > %s) AS cnt
           FROM shards s ORDER BY s.id""",
        (now - ONLINE_WINDOW,))
    sid = next((s["id"] for s in shards if s["cnt"] < SHARD_CAP), None)
    if sid is None:
        sid = q("INSERT INTO shards(name) VALUES(%s) RETURNING id",
                (f"سرور {len(shards) + 1}",), one=True, write=True)["id"]
    q("INSERT INTO presence(user_id, shard_id, last_seen) VALUES(%s, %s, %s)",
      (uid, sid, now), write=True)
    return sid


def shard_name(sid):
    row = q("SELECT name FROM shards WHERE id = %s", (sid,), one=True)
    return row["name"] if row else ""


def online_in_shard(uid, sid):
    row = q("""SELECT 1 AS x FROM presence WHERE user_id = %s AND shard_id = %s AND last_seen > %s""",
            (uid, sid, utcnow() - ONLINE_WINDOW), one=True)
    return bool(row)


@app.errorhandler(Exception)
def on_error(e):
    if isinstance(e, HTTPException):
        return e
    app.logger.exception(e)
    return jsonify(ok=False, error="خطای سرور"), 500


