# ---------------- Auth ----------------

@app.post("/api/register")
def register():
    d = body()
    email = (d.get("email") or "").strip().lower()
    pw = d.get("password") or ""
    name = (d.get("name") or "").strip()
    if not EMAIL_RE.match(email):
        return fail("ایمیل معتبر نیست")
    if len(pw) < 6:
        return fail("رمز باید حداقل ۶ کاراکتر باشد")
    if not (2 <= len(name) <= 20):
        return fail("نام باید ۲ تا ۲۰ کاراکتر باشد")
    if q("SELECT id FROM users WHERE email = %s", (email,), one=True):
        return fail("این ایمیل قبلا ثبت شده")
    row = q("INSERT INTO users(email, password_hash, name, money) VALUES(%s, %s, %s, %s) RETURNING id",
            (email, generate_password_hash(pw), name, START_MONEY), one=True, write=True)
    login_session(row["id"])
    return jsonify(ok=True)


@app.post("/api/login")
def login():
    d = body()
    email = (d.get("email") or "").strip().lower()
    pw = d.get("password") or ""
    row = q("SELECT id, password_hash FROM users WHERE email = %s", (email,), one=True)
    if not row or not check_password_hash(row["password_hash"], pw):
        return fail("ایمیل یا رمز اشتباه است", 401)
    login_session(row["id"])
    return jsonify(ok=True)


@app.post("/api/logout")
def logout():
    uid = session.get("uid")
    if uid:
        q("DELETE FROM presence WHERE user_id = %s", (uid,), write=True)
    session.clear()
    return jsonify(ok=True)


@app.get("/api/me")
def me():
    uid = session.get("uid")
    if not uid:
        return jsonify(ok=False, error="login"), 401
    user = user_row(uid)
    if not user:
        session.clear()
        return jsonify(ok=False, error="login"), 401
    sid = assign_shard(uid)
    return jsonify(ok=True, user=user, shard={"id": sid, "name": shard_name(sid)})


@app.post("/api/heartbeat")
@login_required
def heartbeat():
    sid = assign_shard(g.uid)
    row = q("""SELECT COUNT(*) AS c FROM presence WHERE shard_id = %s AND last_seen > %s""",
            (sid, utcnow() - ONLINE_WINDOW), one=True)
    return jsonify(ok=True, shard={"id": sid, "name": shard_name(sid)}, online=row["c"])


