@app.get("/api/players")
@login_required
def players():
    sid = assign_shard(g.uid)
    rows = q(
        """SELECT u.id, u.name, gg.name AS gang_name
           FROM presence p JOIN users u ON u.id = p.user_id
           LEFT JOIN gangs gg ON gg.id = u.gang_id
           WHERE p.shard_id = %s AND p.last_seen > %s AND u.id <> %s
           ORDER BY u.name""",
        (sid, utcnow() - ONLINE_WINDOW, g.uid))
    return jsonify(ok=True, players=rows)


@app.get("/api/chat")
@login_required
def chat_get():
    since = request.args.get("since", 0, type=int)
    sid = assign_shard(g.uid)
    rows = q(
        """SELECT m.id, m.from_id, m.to_id, m.text, m.created_at, u.name AS from_name
           FROM messages m JOIN users u ON u.id = m.from_id
           WHERE m.id > %s AND ((m.to_id IS NULL AND m.shard_id = %s)
                 OR (m.to_id IS NOT NULL AND (m.to_id = %s OR m.from_id = %s)))
           ORDER BY m.id DESC LIMIT 100""",
        (since, sid, g.uid, g.uid))
    rows.reverse()
    out = [{"id": r["id"], "from_id": r["from_id"], "to_id": r["to_id"], "text": r["text"],
            "from_name": r["from_name"], "created_at": r["created_at"].isoformat()} for r in rows]
    return jsonify(ok=True, messages=out)


@app.post("/api/chat")
@login_required
def chat_post():
    d = body()
    text = (d.get("text") or "").strip()[:300]
    if not text:
        return fail("پیام خالی است")
    sid = assign_shard(g.uid)
    to = d.get("to")
    if to is not None:
        to = int(to)
        if not online_in_shard(to, sid):
            return fail("این بازیکن آنلاین نیست")
    q("INSERT INTO messages(shard_id, from_id, to_id, text) VALUES(%s, %s, %s, %s)",
      (sid, g.uid, to, text), write=True)
    return jsonify(ok=True)


@app.post("/api/signal")
@login_required
def signal_post():
    d = body()
    kind = d.get("kind")
    payload = d.get("payload") or ""
    if kind not in ("offer", "answer", "hangup"):
        return fail("نوع سیگنال نامعتبر است")
    if len(payload) > 40000:
        return fail("داده زیادی است")
    to = int(d.get("to") or 0)
    sid = assign_shard(g.uid)
    if not online_in_shard(to, sid):
        return fail("این بازیکن آنلاین نیست")
    q("INSERT INTO signals(to_id, from_id, kind, payload) VALUES(%s, %s, %s, %s)",
      (to, g.uid, kind, payload), write=True)
    return jsonify(ok=True)


@app.get("/api/signals")
@login_required
def signal_get():
    assign_shard(g.uid)
    rows = q(
        """DELETE FROM signals s USING users u
           WHERE s.to_id = %s AND u.id = s.from_id
           RETURNING s.id, s.from_id, u.name AS from_name, s.kind, s.payload""",
        (g.uid,))
    rows = sorted(rows or [], key=lambda r: r["id"])
    db().commit()
    return jsonify(ok=True, signals=[{"from_id": r["from_id"], "from_name": r["from_name"],
                                      "kind": r["kind"], "payload": r["payload"]} for r in rows])


