@app.post("/api/gang/create")
@login_required
def gang_create():
    name = (body().get("name") or "").strip()
    if not (2 <= len(name) <= 20):
        return fail("نام گنگ باید ۲ تا ۲۰ کاراکتر باشد")
    me_ = user_row(g.uid)
    if me_["gang_id"]:
        return fail("تو الان عضو یک گنگ هستی")
    if me_["money"] < GANG_COST:
        return fail("پول کافی نداری")
    if q("SELECT id FROM gangs WHERE name = %s", (name,), one=True):
        return fail("این اسم گنگ قبلا گرفته شده")
    gid = q("INSERT INTO gangs(name, owner_id) VALUES(%s, %s) RETURNING id",
            (name, g.uid), one=True)["id"]
    q("UPDATE users SET money = money - %s, gang_id = %s WHERE id = %s",
      (GANG_COST, gid, g.uid), write=True)
    return jsonify(ok=True)


@app.post("/api/gang/join")
@login_required
def gang_join():
    gid = int(body().get("gang_id") or 0)
    if user_row(g.uid)["gang_id"]:
        return fail("اول از گنگ فعلی خارج شو")
    if not q("SELECT id FROM gangs WHERE id = %s", (gid,), one=True):
        return fail("گنگ پیدا نشد")
    q("UPDATE users SET gang_id = %s WHERE id = %s", (gid, g.uid), write=True)
    return jsonify(ok=True)


@app.post("/api/gang/leave")
@login_required
def gang_leave():
    me_ = user_row(g.uid)
    gid = me_["gang_id"]
    if not gid:
        return fail("عضو گنگ نیستی")
    owner = q("SELECT owner_id FROM gangs WHERE id = %s", (gid,), one=True)
    if owner and owner["owner_id"] == g.uid:
        q("UPDATE users SET gang_id = NULL WHERE gang_id = %s", (gid,))
        q("DELETE FROM gangs WHERE id = %s", (gid,), write=True)
    else:
        q("UPDATE users SET gang_id = NULL WHERE id = %s", (g.uid,), write=True)
    return jsonify(ok=True)


@app.post("/api/gang/raid")
@login_required
def gang_raid():
    tid = int(body().get("gang_id") or 0)
    me_ = user_row(g.uid)
    if not me_["gang_id"]:
        return fail("اول باید عضو یک گنگ باشی")
    if tid == me_["gang_id"]:
        return fail("نمی‌تونی گنگ خودتو بزنی")
    target = q("SELECT id, name, bank FROM gangs WHERE id = %s", (tid,), one=True)
    if not target:
        return fail("گنگ پیدا نشد")
    if random.random() < 0.5:
        stolen = target["bank"] * 3 // 10
        q("UPDATE gangs SET bank = bank - %s WHERE id = %s", (stolen, tid))
        q("UPDATE gangs SET bank = bank + %s, rp = rp + 20 WHERE id = %s", (stolen, me_["gang_id"]))
        q("UPDATE users SET rp = rp + 10 WHERE id = %s", (g.uid,), write=True)
        if target["bank"] - stolen < 10000:
            q("UPDATE users SET gang_id = NULL WHERE gang_id = %s", (tid,))
            q("DELETE FROM gangs WHERE id = %s", (tid,), write=True)
            return jsonify(ok=True, result="win", destroyed=True, target=target["name"], stolen=stolen)
        return jsonify(ok=True, result="win", target=target["name"], stolen=stolen)
    q("UPDATE gangs SET bank = GREATEST(bank - 5000, 0) WHERE id = %s", (me_["gang_id"],), write=True)
    return jsonify(ok=True, result="lose", target=target["name"])


