@app.post("/api/shop/buy")
@login_required
def shop_buy():
    item = body().get("item")
    if item not in SHOP:
        return fail("این آیتم وجود ندارد")
    price = SHOP[item]["price"]
    if user_row(g.uid)["money"] < price:
        return fail("پول کافی نداری")
    if q("SELECT qty FROM items WHERE user_id = %s AND item = %s AND qty > 0", (g.uid, item), one=True):
        return fail("این آیتم رو قبلا خریدی")
    q("UPDATE users SET money = money - %s WHERE id = %s", (price, g.uid))
    q("""INSERT INTO items(user_id, item, qty) VALUES(%s, %s, 1)
         ON CONFLICT (user_id, item) DO UPDATE SET qty = 1""", (g.uid, item), write=True)
    return jsonify(ok=True)


@app.post("/api/car/buy")
@login_required
def car_buy():
    if user_row(g.uid)["money"] < CAR_PRICE:
        return fail("پول کافی نداری")
    n = q("SELECT COUNT(*) AS c FROM vehicles WHERE owner_id = %s", (g.uid,), one=True)["c"] + 1
    q("UPDATE users SET money = money - %s WHERE id = %s", (CAR_PRICE, g.uid))
    q("INSERT INTO vehicles(owner_id, name) VALUES(%s, %s)", (g.uid, f"ماشین {n}"), write=True)
    return jsonify(ok=True)


@app.post("/api/car/lock")
@login_required
def car_lock():
    vid = int(body().get("vehicle_id") or 0)
    v = q("SELECT id, owner_id, locked FROM vehicles WHERE id = %s", (vid,), one=True)
    if not v or v["owner_id"] != g.uid:
        return fail("این ماشین مال تو نیست")
    q("UPDATE vehicles SET locked = NOT locked WHERE id = %s", (vid,), write=True)
    return jsonify(ok=True, locked=not v["locked"])


@app.post("/api/car/access")
@login_required
def car_access():
    vid = int(body().get("vehicle_id") or 0)
    v = q("SELECT owner_id, locked FROM vehicles WHERE id = %s", (vid,), one=True)
    if not v:
        return fail("ماشین پیدا نشد", 404)
    if v["owner_id"] == g.uid or not v["locked"]:
        return jsonify(ok=True, allowed=True)
    has_tool = q("SELECT 1 AS x FROM items WHERE user_id = %s AND item = 'lockpick' AND qty > 0",
                 (g.uid,), one=True)
    return jsonify(ok=True, allowed=bool(has_tool), reason="" if has_tool else "ماشین قفل است")


@app.post("/api/door/access")
@login_required
def door_access():
    has_tool = q("SELECT 1 AS x FROM items WHERE user_id = %s AND item = 'lockpick' AND qty > 0",
                 (g.uid,), one=True)
    return jsonify(ok=True, allowed=bool(has_tool), reason="" if has_tool else "درب قفل است")


@app.post("/api/game/rp")
@login_required
def game_rp():
    amount = max(0, min(int(body().get("amount") or 0), 50))
    if amount:
        q("UPDATE users SET rp = rp + %s WHERE id = %s", (amount, g.uid), write=True)
    return jsonify(ok=True)


